import numpy as np
from scipy.signal import savgol_filter
from config import logger

class MLPreprocessing:

    def __init__(self, min_counts : int = 25,
                crop_bins_lld : int = 50,
                decimation : int = 8,
                sg_window_length : int = 11,
                sg_polyorder : int = 3):
        """
        Args:
            min_counts (int, optional): Recommended minimum counts threshold for background subtraction. Defaults to 25.
            crop_bins_lld (int, optional): Number of low-energy bins (LLD) to crop. Defaults to 50.
            decimation (int, optional): Decimation factor. Defaults to 8.
            sg_window_length (int, optional): Window length for Savitzky-Golay filter. Expected 5 or larger. Defaults to 11.
            sg_polyorder (int, optional): Polynomial order for Savitzky-Golay filter. Expected 3 or larger. Defaults to 3.
        """
        self.__min_counts = int(min_counts) if min_counts > 0 else 1
        self.__crop_bins_lld = int(crop_bins_lld) if crop_bins_lld > 0 else 0
        self.__decimation = int(decimation) if decimation > 0 else 1
        self.__sg_window_length = int(sg_window_length) if sg_window_length > 0 else 5
        self.__sg_polyorder = int(sg_polyorder) if sg_polyorder > 0 else 3

    def get_min_counts(self):
        return self.__min_counts
    
    def get_crop_bints_lld(self):
        return self.__crop_bins_lld
    
    def get_decimation(self):
        return self.__decimation

    def subtract_background(self, 
                    spectrum_data : list[int],
                    spectrum_live_time : float,
                    bkgnd_data : list[int] = [], 
                    bkgnd_live_time : float = 0.0) -> np.ndarray:
        """Subtracts the passed spectrum data from the background, normalizing background to the spectrum live-time.

        Args:
            spectrum_data (list[int]): List of spectrum counts.
            spectrum_live_time (float): Live-time of the spectrum in seconds.
            bkgnd_data (list[int], optional): List of background counts. Defaults to [].
            bkgnd_live_time (float, optional): Live-time of the background in seconds. Defaults to 0.0.

        Returns:
            np.ndarray: Background-subtracted spectrum with negative values clipped to zero.
        """
        
        if len(bkgnd_data) < 1:
            logger.error(f"No background data provided for subtraction.")
            return np.array(spectrum_data)
        
        if bkgnd_live_time < 1.0:
            logger.error(f"Background live time is {bkgnd_live_time}, less than 1.0 seconds. Background subtraction will not be performed.")
            return np.array(spectrum_data)

        if np.max(bkgnd_data) < self.__min_counts:
            logger.warning(f"Background counts peak is {np.max(bkgnd_data)}, less than {self.__min_counts}. Background subtraction may result in large errors.")
        
        if np.max(spectrum_data) < self.__min_counts:
            logger.warning(f"Spectrum counts peak is {np.max(spectrum_data)}, less than {self.__min_counts}. Background subtraction may result in large errors.")

        # Equalizing background and spectrum data lengths
        n = min(len(spectrum_data), len(bkgnd_data))
        bkgnd_data = np.array(bkgnd_data[:n])
        spectrum_data = np.array(spectrum_data[:n])

        # Normalizing background data based on live-time
        bkgnd_data = bkgnd_data * (spectrum_live_time / bkgnd_live_time)

        # Subtracting background and clipping to 0 to avoid negative values
        return np.clip((spectrum_data - bkgnd_data), 0, None)
    
    def preprocess_log10(self, spectrum_data : np.ndarray) -> np.ndarray:
        """Applies log10 scaling, smoothing, decimation, and normalization to a given spectrum.
        Uses the class attributes defined in the constructor for configuration:
            - crop_bins_lld: how many low-energy bins to crop
            - decimation: decimation factor
            - sg_window_length: window length for Savitzky-Golay filter
            - sg_polyorder: polynomial order for Savitzky-Golay filter

        Args:
            spectrum_data (np.ndarray): Raw spectrum counts.

        Returns:
            np.ndarray: Normalized, decimated, filtered, and log10-scaled spectrum
        """

        # Crop low-energy bins not required for inference
        spectrum_data = spectrum_data[self.__crop_bins_lld:]

        # Log10 scaling
        spectrum_data_log = np.log10(spectrum_data + 1)

        # Smoothinig with Savitzky-Golay filter. Clipping to 0 to avoid negatives
        spectrum_data_filtered = savgol_filter(spectrum_data_log, window_length=self.sg_window_length, polyorder=self.sg_polyorder)
        spectrum_data_filtered = np.clip(spectrum_data_filtered, 0, None)

        # Decimation
        spectrum_data_decimated = spectrum_data_filtered[::self.__decimation]

        # Normalizing to area under the curve, approximated by summing up the counts. Add small epsilon to avoid division by zero
        spectrum_data_normalized = spectrum_data_decimated / (spectrum_data_decimated.sum() + 1e-8)

        return spectrum_data_normalized
    
    def preprocess_pipeline(self,
                spectrum_data : list[int],
                spectrum_live_time : float,
                bkgnd_data : list[int] = [], 
                bkgnd_live_time : float = 0.0) -> np.ndarray:
        """Executes the entire preprocessing pipeline, including background subtraction, log10 scaling, smoothing, decimation, and normalization.

        Args:
            spectrum_data (list[int]): List of spectrum counts.
            spectrum_live_time (float): Live-time of the spectrum in seconds.
            bkgnd_data (list[int], optional): List of background counts. Defaults to [].
            bkgnd_live_time (float, optional): Live-time of the background in seconds. Defaults to 0.0.

        Returns:
            np.ndarray: Normalized, decimated, filtered, and log10-scaled spectrum
        """

        spectrum_no_bk = self._subtract_background(spectrum_data = spectrum_data,
                                                spectrum_live_time = spectrum_live_time,
                                                bkgnd_data = bkgnd_data,
                                                bkgnd_live_time = bkgnd_live_time)        
        
        spectrum_log10 = self._preprocess_log10(spectrum_data = spectrum_no_bk)

        return spectrum_log10



